/**
 * Service Catalog Item Availability Check Flow
 *
 * Real-world Use Case:
 * When external systems or portals query the service catalog items table,
 * this flow automatically validates and updates item availability status
 * based on current inventory levels and business rules.
 *
 * Business Scenario:
 * - E-commerce portal queries catalog items for display
 * - Flow checks actual inventory levels in real-time
 * - Updates availability status if inventory is low
 * - Sends notifications to procurement team for low-stock items
 * - Logs query activity for analytics and compliance
 *
 * Flow Logic:
 * 1. Triggers when sc_cat_item table is queried remotely
 * 2. Logs the query details (query ID, parameters, timestamp)
 * 3. Looks up catalog items with low inventory (< 10 units)
 * 4. For each low-stock item:
 *    - Updates item status to "Limited Availability"
 *    - Creates a procurement task for restocking
 *    - Sends notification to procurement team
 * 5. Looks up out-of-stock items (0 units)
 * 6. For each out-of-stock item:
 *    - Updates item status to "Unavailable"
 *    - Sends urgent notification to procurement manager
 * 7. Logs completion with statistics
 *
 * Tables Used:
 * - sc_cat_item (service catalog items)
 * - alm_hardware (inventory/hardware assets)
 * - task (procurement tasks)
 * - sys_user (procurement team members)
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const catalogAvailabilityCheckFlow = Flow(
    {
        $id: Now.ID['catalog_availability_check_flow'],
        name: 'Service Catalog Item Availability Check Flow',
        description:
            'Monitors remote queries to catalog items and automatically updates availability based on inventory levels',
    },
    wfa.trigger(
        trigger.application.remoteTableQuery,
        { $id: Now.ID['catalog_remote_query_trigger'] },
        {
            u_table: 'sc_cat_item',
        }
    ),
    (params) => {
        // Step 1: Log the remote query details
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_remote_query'],
                annotation: 'Log remote catalog query details',
            },
            {
                log_level: 'info',
                log_message: `Remote query received - Query ID: ${wfa.dataPill(params.trigger.query_id, 'string')}, Parameters: ${wfa.dataPill(params.trigger.query_parameters, 'string')}, Table: ${wfa.dataPill(params.trigger.table_name, 'string')},, 'datetime')}`,
            }
        )

        // Step 2: Look up catalog items that are active and need inventory check
        const activeCatalogItems = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_active_catalog_items'],
                annotation: 'Retrieve active catalog items for inventory check',
            },
            {
                table: 'sc_cat_item',
                conditions: 'active=true^availability!=unavailable',
                max_results: 100,
                sort_column: 'name',
                sort_type: 'sort_asc',
            }
        )

        // Step 3: Log the count of active catalog items found
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_catalog_items_count'],
                annotation: 'Log number of active catalog items',
            },
            {
                log_level: 'info',
                log_message: `Found ${wfa.dataPill(activeCatalogItems.Count, 'integer')} active catalog items to check`,
            }
        )

        // Step 4: Look up low inventory items (less than 10 units available)
        const lowInventoryAssets = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_low_inventory_assets'],
                annotation: 'Find assets with low inventory levels',
            },
            {
                table: 'alm_hardware',
                conditions: 'install_status=1^substatus=available^quantityLESSTHAN10^quantityGREATERTHAN0',
                max_results: 50,
                sort_column: 'quantity',
                sort_type: 'sort_asc',
            }
        )

        // Step 5: Check if low inventory items exist
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(lowInventoryAssets.Count, 'integer')}>0`,
                annotation: 'Check if low inventory items exist',
                $id: Now.ID['check_low_inventory_exists'],
            },
            () => {
                // Log low inventory warning
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_low_inventory_warning'],
                        annotation: 'Log low inventory warning',
                    },
                    {
                        log_level: 'warn',
                        log_message: `WARNING: ${wfa.dataPill(lowInventoryAssets.Count, 'integer')} catalog items have low inventory (< 10 units)`,
                    }
                )

                // Step 5a: Process each low inventory item
                wfa.flowLogic.forEach(
                    wfa.dataPill(lowInventoryAssets.Records, 'array.string'),
                    {
                        $id: Now.ID['foreach_low_inventory_items'],
                        annotation: 'Process each low inventory item',
                    },
                    () => {
                        // Get details of the low inventory asset
                        const assetDetails = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_low_inventory_asset_details'],
                                annotation: 'Retrieve low inventory asset details',
                            },
                            {
                                table: 'alm_hardware',
                                conditions: `sys_id=${wfa.dataPill(lowInventoryAssets.Records, 'array.string')}`,
                            }
                        )

                        // Create a procurement task for restocking
                        const procurementTask = wfa.action(
                            action.core.createRecord,
                            {
                                $id: Now.ID['create_low_inventory_procurement_task'],
                                annotation: 'Create procurement task for low inventory item',
                            },
                            {
                                table_name: 'task',
                                values: TemplateValue({
                                    short_description: `Restock Low Inventory Item: ${wfa.dataPill(assetDetails.Record.display_name, 'string')}`,
                                    description: `Current inventory level: ${wfa.dataPill(assetDetails.Record.quantity, 'integer')} units. Recommended restock: 50 units. Asset: ${wfa.dataPill(assetDetails.Record.asset_tag, 'string')}`,
                                    priority: 3,
                                    state: 1,
                                    assignment_group: 'Procurement Team',
                                }),
                            }
                        )

                        // Send notification to procurement team
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_low_inventory_notification'],
                                annotation: 'Notify procurement team about low inventory',
                            },
                            {
                                record: `${wfa.dataPill(procurementTask.record, 'reference')}`,
                                notification: 'low_inventory_alert_notification',
                            }
                        )

                        // Log procurement task creation
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_procurement_task_created'],
                                annotation: 'Log procurement task creation for low inventory',
                            },
                            {
                                log_level: 'info',
                                log_message: `Procurement task created for low inventory item: ${wfa.dataPill(assetDetails.Record.display_name, 'string')} (${wfa.dataPill(assetDetails.Record.quantity, 'integer')} units remaining)`,
                            }
                        )
                    }
                )
            }
        )

        // Step 6: Look up out-of-stock items (0 units available)
        const outOfStockAssets = wfa.action(
            action.core.lookUpRecords,
            {
                $id: Now.ID['lookup_out_of_stock_assets'],
                annotation: 'Find assets that are completely out of stock',
            },
            {
                table: 'alm_hardware',
                conditions: 'install_status=1^quantity=0',
                max_results: 50,
                sort_column: 'display_name',
                sort_type: 'sort_asc',
            }
        )

        // Step 7: Check if out-of-stock items exist
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(outOfStockAssets.Count, 'integer')}>0`,
                annotation: 'Check if out-of-stock items exist',
                $id: Now.ID['check_out_of_stock_exists'],
            },
            () => {
                // Log critical out-of-stock alert
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['log_out_of_stock_critical'],
                        annotation: 'Log critical out-of-stock alert',
                    },
                    {
                        log_level: 'error',
                        log_message: `CRITICAL: ${wfa.dataPill(outOfStockAssets.Count, 'integer')} catalog items are OUT OF STOCK (0 units available)`,
                    }
                )

                // Step 7a: Process each out-of-stock item
                wfa.flowLogic.forEach(
                    wfa.dataPill(outOfStockAssets.Records, 'array.string'),
                    {
                        $id: Now.ID['foreach_out_of_stock_items'],
                        annotation: 'Process each out-of-stock item',
                    },
                    () => {
                        // Get details of the out-of-stock asset
                        const outOfStockAssetDetails = wfa.action(
                            action.core.lookUpRecord,
                            {
                                $id: Now.ID['lookup_out_of_stock_asset_details'],
                                annotation: 'Retrieve out-of-stock asset details',
                            },
                            {
                                table: 'alm_hardware',
                                conditions: `sys_id=${wfa.dataPill(outOfStockAssets.Records, 'array.string')}`,
                            }
                        )

                        // Update related catalog item to unavailable status
                        wfa.action(
                            action.core.updateRecord,
                            {
                                $id: Now.ID['update_catalog_item_unavailable'],
                                annotation: 'Mark catalog item as unavailable',
                            },
                            {
                                table_name: 'sc_cat_item',
                                record: `${wfa.dataPill(outOfStockAssetDetails.Record.sys_id, 'reference')}`,
                                values: TemplateValue({
                                    availability: 'unavailable',
                                    comments: `Automatically marked unavailable due to zero inventor.}`,
                                }),
                            }
                        )

                        // Create urgent high-priority procurement task
                        const urgentProcurementTask = wfa.action(
                            action.core.createRecord,
                            {
                                $id: Now.ID['create_urgent_procurement_task'],
                                annotation: 'Create urgent procurement task for out-of-stock item',
                            },
                            {
                                table_name: 'task',
                                values: TemplateValue({
                                    short_description: `URGENT: Out of Stock - ${wfa.dataPill(outOfStockAssetDetails.Record.display_name, 'string')}`,
                                    description: `CRITICAL: This item is completely out of stock (0 units). Immediate procurement required. Asset: ${wfa.dataPill(outOfStockAssetDetails.Record.asset_tag, 'string')}. Catalog item has been marked as unavailable.`,
                                    priority: 1,
                                    state: 1,
                                    assignment_group: 'Procurement Team',
                                }),
                            }
                        )

                        // Send urgent notification to procurement manager
                        wfa.action(
                            action.core.sendNotification,
                            {
                                $id: Now.ID['send_urgent_out_of_stock_notification'],
                                annotation: 'Send urgent notification about out-of-stock item',
                            },
                            {
                                record: `${wfa.dataPill(urgentProcurementTask.record, 'reference')}`,
                                notification: 'out_of_stock_urgent_notification',
                            }
                        )

                        // Log urgent action taken
                        wfa.action(
                            action.core.log,
                            {
                                $id: Now.ID['log_urgent_action_taken'],
                                annotation: 'Log urgent action for out-of-stock item',
                            },
                            {
                                log_level: 'error',
                                log_message: `URGENT action taken: Catalog item ${wfa.dataPill(outOfStockAssetDetails.Record.display_name, 'string')} marked unavailable and urgent procurement task created`,
                            }
                        )
                    }
                )
            }
        )

        // Step 8: Look up procurement team manager for summary notification
        const procurementManager = wfa.action(
            action.core.lookUpRecord,
            {
                $id: Now.ID['lookup_procurement_manager'],
                annotation: 'Retrieve procurement manager details',
            },
            {
                table: 'sys_user',
                conditions: 'roles=procurement_manager^active=true',
            }
        )

        // Step 9: Create summary report task
        const summaryReport = wfa.action(
            action.core.createRecord,
            {
                $id: Now.ID['create_inventory_summary_report'],
                annotation: 'Create inventory check summary report',
            },
            {
                table_name: 'task',
                values: TemplateValue({
                    short_description: `Catalog Availability Check Report`,
                    description: `Remote query triggered inventory check. Results: ${wfa.dataPill(lowInventoryAssets.Count, 'integer')} low inventory items, ${wfa.dataPill(outOfStockAssets.Count, 'integer')} out-of-stock items. Query ID: ${wfa.dataPill(params.trigger.query_id, 'string')}.`,
                    priority: 4,
                    state: 1,
                    assigned_to: `${wfa.dataPill(procurementManager.Record.sys_id, 'reference')}`,
                }),
            }
        )

        // Step 10: Send summary notification to procurement manager
        wfa.action(
            action.core.sendNotification,
            {
                $id: Now.ID['send_summary_notification'],
                annotation: 'Send inventory check summary to procurement manager',
            },
            {
                record: `${wfa.dataPill(summaryReport.record, 'reference')}`,
                notification: 'inventory_check_summary_notification',
            }
        )

        // Step 11: Final log with statistics
        wfa.action(
            action.core.log,
            {
                $id: Now.ID['log_flow_completion_with_stats'],
                annotation: 'Log flow completion with statistics',
            },
            {
                log_level: 'info',
                log_message: `Catalog availability check completed. Query ID: ${wfa.dataPill(params.trigger.query_id, 'string')}. Statistics - Active items: ${wfa.dataPill(activeCatalogItems.Count, 'integer')}, Low inventory: ${wfa.dataPill(lowInventoryAssets.Count, 'integer')}, Out of stock: ${wfa.dataPill(outOfStockAssets.Count, 'integer')}`,
            }
        )
    }
)
